import heapq


def _quota_intervals(capacity, tie):
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in set(data.get("blocked", []))]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        k = data["k"]
        best_value = None
        best_ids = None

        for mask in range(1 << len(jobs)):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(len(jobs)) if mask & (1 << i)]
            ids = {job["id"] for job in selected}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active_ends = []
            valid = True
            for job in sorted(selected, key=lambda row: (row["start"], row["end"])):
                active_ends = [end for end in active_ends if end > job["start"]]
                if len(active_ends) >= capacity:
                    valid = False
                    break
                active_ends.append(job["end"])
            if not valid:
                continue

            value = sum(job["value"] for job in selected)
            id_list = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (id_list < best_ids if tie == "smallest" else id_list > best_ids))):
                best_value, best_ids = value, id_list

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            mode = data["rounding"]
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = [[-1] + sorted(row["version"] for row in packages[name])
                   for name in names]

        for vector in product(*choices):
            selected = {name: version for name, version in zip(names, vector)
                        if version != -1}
            if any(name not in selected or not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue
            if any(name in selected and selected[name] != version
                   for name, version in pins.items()):
                continue
            if any(name in selected and selected[name] in blocked.get(name, [])
                   for name in names):
                continue

            edges = {name: [] for name in selected}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name] if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = selected.get(target)
                    if (target_version is None or
                            not dep["min"] <= target_version <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            closure = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in closure:
                    continue
                closure.add(name)
                stack.extend(edges.get(name, []))
            if closure != set(selected):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if all(visit(name) for name in selected):
                return {"versions": selected}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start_mask = bit.get(source, 0)
        initial = (source, start_mask, data["coupons"])
        best = {initial: data["start"]}
        queue = [(data["start"], source, start_mask, data["coupons"])]
        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if best.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons)]
                if coupons:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, coupons - 1))
                for duration, remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, remaining)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, remaining))
        return {"arrival": None}
    return solve


